            ['key' => 'tos_questions_contact', 'english' => 'For any questions about these TOS, please contact us at', 'mexican_spanish' => 'Para cualquier pregunta sobre estos TOS, por favor contáctanos en', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'tos_agreement', 'english' => 'By accessing and using the services provided by tContractor.com, you agree to comply with and be bound by the following Terms of Service. Please review them carefully before usage of the site. If you do not agree to these terms, you should not review information or services from this site.', 'mexican_spanish' => 'Al acceder y utilizar los servicios proporcionados por tContractor.com, aceptas cumplir y estar sujeto a los siguientes Términos de Servicio. Por favor, revísalos cuidadosamente antes de usar el sitio. Si no estás de acuerdo con estos términos, no debes revisar información o servicios de este sitio.', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'join_our_network_of_contractors', 'english' => 'Join Our Network of Contractors', 'mexican_spanish' => 'Únete a Nuestra Red de Contratistas', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'building_community_at_tcontractor', 'english' => "At tcontractor.com, we're building a community where contractors help each other succeed. Whether you're looking to hire, seek guidance, or find new opportunities, you're in the right place.", 'mexican_spanish' => 'En tcontractor.com, estamos construyendo una comunidad donde los contratistas se ayudan entre sí para tener éxito. Ya sea que esté buscando contratar, buscar orientación o encontrar nuevas oportunidades, está en el lugar correcto.', 'created_at' => now(), 'updated_at' => now()],
