            ['key' => 'find_skilled_professionals', 'english' => 'Find skilled professionals and grow your projects. Navigate through our vast network of contractors to hire experienced individuals in various fields.', 'mexican_spanish' => 'Encuentra profesionales cualificados y haz crecer tus proyectos. Navegue a través de nuestra amplia red de contratistas para contratar personas con experiencia en diversos campos.', 'created_at' => now(), 'updated_at' => now()],
