            ['key' => 'share_your_contractor_page_with_others', 'english' => 'Share Your Contractor Page With Others:', 'mexican_spanish' => 'Comparte Tu Página de Contratista con Otros:', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'unlimited', 'english' => 'Unlimited', 'mexican_spanish' => 'Ilimitado', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'what_is_the_news_feed', 'english' => 'What is the News Feed?', 'mexican_spanish' => '¿Qué es el Feed de Noticias?', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'the_news_feed_is_the_heart', 'english' => 'The News Feed is the heart of tContractor. This is the focal point of all the action going on in and around your geographical area.', 'mexican_spanish' => 'El Feed de Noticias es el corazón de tContractor. Este es el punto focal de toda la acción que ocurre en y alrededor de tu área geográfica.', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'use_the_news_feed_community', 'english' => "Use the News Feed Community to help you run your business smarter & more profitably with fewer headaches! For best results, Scan the News Feed posts daily to get ideas, educate yourself, find people/contractors you can trust to hire or work for, Look for availability of jobs and so much more!", 'mexican_spanish' => 'Usa la Comunidad del Feed de Noticias para ayudarte a administrar tu negocio de manera más inteligente y rentable con menos dolores de cabeza!...', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'advertise_your_services', 'english' => 'Advertise your services! Let other Contractors know what you specialize in!', 'mexican_spanish' => '¡Anuncia tus servicios! Haz saber a otros Contratistas en qué te especializas!', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'post_often_to', 'english' => 'Post often to:', 'mexican_spanish' => 'Publica a menudo en:', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'put_your_brag_out_there', 'english' => 'Put your \'Brag\' out there often. Show pictures of your work before & after. Build your Brand...', 'mexican_spanish' => 'Publica tu \'Alarde\' a menudo. Muestra fotos de tu trabajo antes y después. Construye tu Marca...', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'post_new_jobs_coming_up', 'english' => 'Post new jobs coming up that you may need help with?', 'mexican_spanish' => '¿Publicar nuevos trabajos que se avecinan con los que puedas necesitar ayuda?', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'got_a_question_post_it', 'english' => 'Got a question? Post it on the News Feed!', 'mexican_spanish' => '¿Tienes una pregunta? ¡Publícala en el Feed de Noticias!', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'ran_into_a_situation_post_it', 'english' => 'Ran into a situation? Not sure of the best option? Post It!', 'mexican_spanish' => '¿Te encontraste con una situación? ¿No estás seguro de la mejor opción? ¡Publícala!', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'why_tcontractor', 'english' => 'Why tContractor? We have Facebook, Instagram or Twitter!', 'mexican_spanish' => '¿Por qué tContractor? ¡Tenemos Facebook, Instagram o Twitter!', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'true_social_media_platforms_offer', 'english' => "True, these other Social Media platforms offer the community. But that community is diverse, with retail customers intermixed with contractors & sub-contractors. It's hard to have a detailed conversation when the retail customer, and maybe yours, gets to read along with you! Plus, most of these communities are spread out over the entire world. What works in Texas may not work in California or New York! Or how hard is it to find a good quality contractor / sub-contractor that you have good reason to trust on one of these sites?", 'mexican_spanish' => 'Es cierto que estas otras plataformas de redes sociales ofrecen a la comunidad. Pero esa comunidad es diversa, con clientes minoristas mezclados con contratistas y subcontratistas. ¡Es difícil tener una conversación detallada cuando el cliente minorista, y tal vez el suyo, lee junto con usted! Además, la mayoría de estas comunidades están repartidas por todo el mundo. ¡Lo que funciona en Texas puede no funcionar en California o Nueva York! ¿O qué tan difícil es encontrar un contratista/subcontratista de buena calidad en el que tenga buenas razones para confiar en uno de estos sitios?', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'is_the_answer_to_these_issues', 'english' => "is the answer to these issues. We are in the process of building a nationwide community of contractors that you can have access to, but we focus on local areas. See posts that only pertain to your trade, or see everything. It's your choice. Look for contractors for specific trades locally. And, more importantly, choose a contractor you can trust that has been truly reviewed by your peers!", 'mexican_spanish' => 'es la respuesta a estas cuestiones. Estamos en el proceso de construir una comunidad nacional de contratistas a la que usted pueda tener acceso, pero nos enfocamos en áreas locales. Vea publicaciones que solo pertenecen a su negocio o vea todo. Es tu elección. Busque contratistas para oficios específicos a nivel local. Y, lo que es más importante, elija un contratista en el que pueda confiar y que haya sido realmente revisado por sus pares.', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'how_much_does_it_cost_to_advertise', 'english' => 'How much does it cost to advertise my company on tContractor?', 'mexican_spanish' => '¿Cuánto cuesta anunciar mi empresa en tContractor?', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'member_contractor_advertises_free', 'english' => 'Member Contractor advertises their business for free via News Feed postings. We offer a FREE service with limited postings per month, but if you want/need more, subscribe and gain all the advantages of', 'mexican_spanish' => 'El contratista miembro anuncia su negocio de forma gratuita a través de publicaciones en la sección de noticias. Ofrecemos un servicio GRATUITO con publicaciones limitadas por mes, pero si quieres/necesitas más, suscríbete y obtén todas las ventajas de', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'what_is_sub_finder', 'english' => 'What is Sub-Finder?', 'mexican_spanish' => '¿Qué es Sub-Finder?', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'sub_finder_allows_you_to_find', 'english' => 'Sub-Finder allows you to find the right contractor/sub-contractor that fits your needs and cost! Use Sub-Finder to search for subs by city, region, state, name, trade, and more. If you upgrade from the FREE version, you can even save personal notes about that contractor and rate them as a Preferred contractor, Backup contractor, Possible, or reject them.', 'mexican_spanish' => '¡Sub-Finder le permite encontrar el contratista/subcontratista adecuado que se ajuste a sus necesidades y costos! Utilice Sub-Finder para buscar suscriptores por ciudad, región, estado, nombre, comercio y más. Si actualiza desde la versión GRATUITA, puede incluso guardar notas personales sobre ese contratista y calificarlas como contratista preferido, contratista de respaldo, posible o rechazarlas.', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'simple_but_powerful', 'english' => 'SIMPLE BUT POWERFUL!', 'mexican_spanish' => '¡SIMPLE PERO PODEROSO!', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'have_you_ever_had_a_customer', 'english' => 'Have you ever had a customer, sales rep, or another contractor you wouldn\'t wish on your worst enemy?', 'mexican_spanish' => '¿Alguna vez has tenido un cliente, representante de ventas o otro contratista que no le desearías a tu peor enemigo?', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'they_are_out_there', 'english' => 'Well, they are out there! If you\'ve been in business long enough, you know that not all customers/jobs are good for you!', 'mexican_spanish' => '¡Pues, están ahí fuera! Si has estado en el negocio lo suficientemente tiempo, sabes que no todos los clientes/trabajos son buenos para ti!', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'would_you_like_to_know_experiences', 'english' => 'Would you like to know some of the experiences others had with a customer before you decide to do business with them? Check the Red Flag before you sign a contract with them. Could save you money and headaches!', 'mexican_spanish' => '¿Le gustaría conocer algunas de las experiencias que otros tuvieron con un cliente antes de decidirse a hacer negocios con él? Consulte la Bandera Roja antes de firmar un contrato con ellos. ¡Podría ahorrarle dinero y dolores de cabeza!', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'as_a_contractor_you_are_always_under_review', 'english' => 'As a contractor, you are always under review; here\'s your chance to review those underhanded players! Keep them accountable!', 'mexican_spanish' => 'Como contratista, siempre estás bajo revisión; ¡aquí tienes la oportunidad de evaluar a esos jugadores deshonestos! Mantenlos responsables!', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'more_business_more_profit_less_headaches', 'english' => 'More Business, More Profit, Less Headaches - What?', 'mexican_spanish' => 'Más Negocio, Más Ganancias, Menos Dolores de Cabeza - ¿Qué?', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'sounds_great_how_do_i_do_this', 'english' => 'Sounds Great… How Do I Do This?', 'mexican_spanish' => 'Suena Genial... ¿Cómo lo Hago?', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'with', 'english' => 'With', 'mexican_spanish' => 'Con', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'its_easy', 'english' => 'it\'s easy!', 'mexican_spanish' => '¡es fácil!', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'heres_a_simple_example', 'english' => "Here's a simple example: You're a Painter or a Carpenter, or a member of any Trade. You are on a job, and you have a good rapport with your customers; they mention that they are interested in a new cement patio or flooring.", 'mexican_spanish' => 'Aquí tienes un ejemplo sencillo: eres pintor, carpintero o miembro de cualquier oficio. Tiene un trabajo y tiene una buena relación con sus clientes; mencionan que están interesados en un nuevo patio o piso de cemento.', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'most_contractors_would_refuse', 'english' => 'Most contractors would refuse the opportunity or not take it seriously because they do not have the time, experience, how to bid, and so on.', 'mexican_spanish' => 'La mayoría de los contratistas rechazarían la oportunidad o no la tomarían en serio porque no tienen el tiempo, la experiencia, cómo licitar, y así sucesivamente.', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'you_can_now_have_the_tools', 'english' => 'you can now have the tools to do the job! Easily find the sub you can trust to represent you through Sub-Finder. Use the News Feed to answer your questions & and become more proficient with that trade; easily get the ins & outs!', 'mexican_spanish' => '¡Ahora puedes tener las herramientas para hacer el trabajo! Encuentre fácilmente el submarino en el que puede confiar para que lo represente a través de Sub-Finder. Utilice la sección de noticias para responder sus preguntas y volverse más competente en ese oficio; ¡Obtenga fácilmente los entresijos!', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'or_heres_another', 'english' => 'OR Here\'s another…', 'mexican_spanish' => 'O Aquí hay otro...', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'youre_a_roofer_or_general_contractor', 'english' => "You're a Roofer or General Contractor. You have a customer 50 miles away, and your normal Painter doesn't want to travel so far. What do you do? Go hire someone off the internet, social media, a friend of a friend, or even a painter you met at a gas station - No.", 'mexican_spanish' => 'Eres techador o contratista general. Tienes un cliente a 50 millas de distancia y tu pintor normal no quiere viajar tan lejos. ¿A qué te dedicas? Contrata a alguien de Internet, de las redes sociales, al amigo de un amigo o incluso a un pintor que conociste en una gasolinera. No.', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'use_tcontractors_sub_finder', 'english' => 'Use tContractor\'s Sub-Finder to find a Painter in that city or close by. A painter that has good reviews in', 'mexican_spanish' => 'Usa el Sub-Finder de tContractor para encontrar un Pintor en esa ciudad o cerca. Un pintor que tenga buenas reseñas en', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'someone_you_can_reasonably_trust', 'english' => 'Someone you can reasonably trust to represent your name. Less Headaches: The customer is happy with your quick turnaround, and you look good! You are Happy! NEXT!', 'mexican_spanish' => 'Alguien en quien puedas confiar razonablemente para representar tu nombre. Menos Dolores de Cabeza: El cliente está contento con tu rápida respuesta, y tú luces bien! ¡Estás Feliz! ¡SIGUIENTE!', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'what_are_trades', 'english' => 'What are Trades?', 'mexican_spanish' => '¿Qué son los Oficios?', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'for_example', 'english' => 'For example', 'mexican_spanish' => 'Por ejemplo', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'if_you_do_not_care_about_roofing', 'english' => 'if you do not care about Roofing, turn that group off so you will not see postings referring to Roofing.', 'mexican_spanish' => 'si no te interesa la Techumbre, desactiva ese grupo para no ver publicaciones referentes a la Techumbre.', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'this_is_your_default_information', 'english' => 'This is your default information and can be changed at anytime. ', 'mexican_spanish' => 'Esta es tu información predeterminada y puede ser cambiada en cualquier momento.', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'no_contractor_found', 'english' => 'No Contractor Found', 'mexican_spanish' => 'No se Encontró Contratista', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'people_who_liked_the_post', 'english' => 'People who liked the post', 'mexican_spanish' => 'Personas a las que les gustó la publicación', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'people_who_disliked_the_post', 'english' => 'People who disliked the post', 'mexican_spanish' => 'Personas a las que no les gustó la publicación', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'do_you_wish_to_share_this_post', 'english' => 'Do you wish to share this post with your audience?', 'mexican_spanish' => '¿Deseas compartir esta publicación con tu audiencia?', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'write_a_comment', 'english' => 'Write a Comment...', 'mexican_spanish' => 'Escribe un Comentario...', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'comment_text', 'english' => 'Comment Text', 'mexican_spanish' => 'Texto del Comentario', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'reposting_allows_you_to_share', 'english' => 'Reposting allows you to share this post with your followers, spreading the message further.', 'mexican_spanish' => 'Republicar te permite compartir esta publicación con tus seguidores, difundiendo aún más el mensaje.', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'no_comments_yet', 'english' => 'No Comments Yet', 'mexican_spanish' => 'Aún No Hay Comentarios', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'no_more_comments_to_load', 'english' => 'No More Comments to Load', 'mexican_spanish' => 'No Hay Más Comentarios para Cargar', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'delete', 'english' => 'Delete', 'mexican_spanish' => 'Eliminar', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'do_you_want_to_delete_this_comment', 'english' => 'Do you want to Delete this comment?', 'mexican_spanish' => '¿Quieres Eliminar este comentario?', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'updating', 'english' => 'Updating', 'mexican_spanish' => 'Actualizando', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'do_you_want_to_delete_this_reply', 'english' => 'Do you want to Delete this reply?', 'mexican_spanish' => '¿Quieres Eliminar esta respuesta?', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'edit_post', 'english' => 'Edit Post', 'mexican_spanish' => 'Editar Publicación', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'trades_are_what_you_do', 'english' => 'Trades are what you do… If you are a landscaper, you would be a member of the Landscaping Trade Group. If you are a Painter, you would be a member of the Painting & Staining Group. Same if you did Concrete, you would be a member of the Concrete, Masonry & Foundations Group.', 'mexican_spanish' => 'Trades are what you do… If you are a landscaper, you would be a member of the Landscaping Trade Group. If you are a Painter, you would be a member of the Painting & Staining Group. Same if you did Concrete, you would be a member of the Concrete, Masonry & Foundations Group.', 'created_at' => now(), 'updated_at' => now()],
            ['key' => 'has_26_plus_trade_groups', 'english' => 'has 26+ trade groups.', 'mexican_spanish' => 'tiene más de 26 grupos de oficios.', 'created_at' => now(), 'updated_at' => now()],
